import django.core.validators
from decimal import Decimal
from django.db import migrations, models


def scores_to_points(apps, schema_editor):
    """Old scores went from 0 to 10 and gave score / 10 × extra_points; the
    grade is now those points."""
    PathwayGrade = apps.get_model("pathways", "PathwayGrade")
    grades = PathwayGrade.objects.select_related(
        "pathway_enrollment__offering__pathway"
    )
    for grade in grades:
        max_score = grade.pathway_enrollment.offering.pathway.extra_points
        grade.score = (grade.score / 10 * max_score).quantize(Decimal("0.01"))
        grade.save(update_fields=["score"])


